xpath.script:
(function() {
    // 1. Détection Immédiate Ultra Rapide pour éviter tout clignotement
    function checkAndApplyRole(isGerant) {
        if (isGerant) {
            document.documentElement.classList.add('o_resto_gerant_mode');
            if (document.body) document.body.classList.add('o_resto_gerant_mode');
        } else {
            document.documentElement.classList.remove('o_resto_gerant_mode');
            if (document.body) document.body.classList.remove('o_resto_gerant_mode');
        }
    }

    var sInfo = window.odoo && (window.odoo.__session_info__ || window.odoo.session_info);
    var cachedIsGerant = localStorage.getItem('resto_is_gerant');

    if (sInfo && typeof sInfo.is_restaurant_manager !== 'undefined') {
        checkAndApplyRole(Boolean(sInfo.is_restaurant_manager));
    } else if (sInfo && sInfo.uid) {
        var isG = Boolean(sInfo.uid !== 2 && !sInfo.is_system);
        checkAndApplyRole(isG);
    } else if (cachedIsGerant !== null) {
        checkAndApplyRole(cachedIsGerant === 'true');
    }

    var cachedName = localStorage.getItem('resto_brand_name') || '';
    var cachedSub = localStorage.getItem('resto_brand_subtitle') || '';
    var cachedLogo = localStorage.getItem('resto_brand_logo') || '/web/binary/company_logo';

    function renderOrUpdateBrand(data) {
        var navbar = document.querySelector('.o_main_navbar');
        if (!navbar) return;

        var isGerant = false;
        if (data && typeof data.is_gerant !== 'undefined') {
            isGerant = Boolean(data.is_gerant);
        } else if (sInfo && typeof sInfo.is_restaurant_manager !== 'undefined') {
            isGerant = Boolean(sInfo.is_restaurant_manager);
        } else if (sInfo && sInfo.uid) {
            isGerant = Boolean(sInfo.uid !== 2 && !sInfo.is_system);
        } else {
            isGerant = (localStorage.getItem('resto_is_gerant') === 'true');
        }

        checkAndApplyRole(isGerant);

        // Conteneur de Marque
        var brand = navbar.querySelector('.o_restaurant_brand_container');
        if (!brand) {
            brand = document.createElement('div');
            brand.className = 'o_restaurant_brand_container';
            navbar.insertBefore(brand, navbar.firstChild);
        }

        var logoUrl = (data && data.logo_url) ? data.logo_url : cachedLogo;
        var rName = (data && data.name) ? data.name : (cachedName || 'RESTAURANT');
        var rSub = (data && data.subtitle) ? data.subtitle : cachedSub;

        if (isGerant) {
            brand.innerHTML = [
                '<div class="o_restaurant_logo_card">',
                ' <img src="' + logoUrl + '" alt="Logo" class="o_restaurant_logo_img"/>',
                '</div>',
                '<div class="o_restaurant_brand_text_block">',
                ' <div class="o_restaurant_brand_name">' + rName + '</div>',
                ' <div class="o_restaurant_brand_badge"> ESPACE GÉRANT </div>',
                '</div>'
            ].join('');
            brand.onclick = function() {
                window.location.hash = '#action=restaurant_core.action_restaurant_gerant_own_orders';
            };

            // Bouton d\'action rapide caisse
            var systray = navbar.querySelector('.o_menu_systray');
            var existingBtn = navbar.querySelector('.o_gerant_quick_pos_btn');
            if (!existingBtn) {
                var quickBtn = document.createElement('a');
                quickBtn.className = 'o_gerant_quick_pos_btn';
                quickBtn.href = '/pos/ui?config_id='+ (data && data.pos_config_id ? data.pos_config_id : 2);
                quickBtn.innerHTML = ' Ouvrir la Caisse ';
                if (systray) {
                    navbar.insertBefore(quickBtn, systray);
                } else {
                    navbar.appendChild(quickBtn);
                }
            }
        } else {
            brand.innerHTML = [
                '<div class="o_restaurant_logo_card">',
                ' <img src="' + logoUrl + '" alt="Logo" class="o_restaurant_logo_img"/>',
                '</div>',
                '<div class="o_restaurant_brand_name">' + rName + '</div>',
                '<div class="o_restaurant_brand_subtitle">' + rSub + '</div>'
            ].join('');
            brand.onclick = function() {
                if (window.odoo && window.odoo.__WOWL_DEBUG__ && window.odoo.__WOWL_DEBUG__.root) {
                    var env = window.odoo.__WOWL_DEBUG__.root.env;
                    if (env && env.services && env.services.action) {
                        if (env.services.menu) {
                            var apps = env.services.menu.getApps();
                            var restoApp = apps && apps.find(function(a) {
                                return a.xmlid === 'restaurant_core.menu_restaurant_root' || (a.name && a.name.indexOf('Restaurant') !== -1);
                            });
                            if (restoApp && env.services.menu.setCurrentMenu) {
                                env.services.menu.setCurrentMenu(restoApp);
                            }
                        }
                        env.services.action.doAction("restaurant_core.action_restaurant_sales_dashboard", { clearBreadcrumbs: true });
                        return;
                    }
                }
                window.location.hash = '#action=restaurant_core.action_restaurant_sales_dashboard';
            };
        }

        if (data) {
            if (data.name) localStorage.setItem('resto_brand_name', data.name);
            if (data.subtitle) localStorage.setItem('resto_brand_subtitle', data.subtitle);
            if (data.logo_url) localStorage.setItem('resto_brand_logo', data.logo_url);
            localStorage.setItem('resto_is_gerant', isGerant ? 'true' : 'false');
        }
    }

    var ADMIN_MENU_CONFIG = [
        { name: "Gérants du Restaurant", action: 414, menuId: 259, xmlid: "restaurant_core.menu_restaurant_managers" },
        { name: "Menus & Plats", action: 415, menuId: 265, xmlid: "restaurant_core.menu_restaurant_dishes_all" },
        { name: "Sessions & Horaires des Gérants", action: 421, menuId: 270, xmlid: "restaurant_core.menu_restaurant_sessions" },
        { name: "Commandes & Ventes Encaissées", action: "restaurant_core.action_restaurant_sales_monitoring", menuId: 261, xmlid: "restaurant_core.menu_restaurant_orders" },
        { name: "Facturation & DGI", action: 424, menuId: 274, xmlid: "restaurant_core.menu_restaurant_invoices" },
        { name: "Configuration Restaurant & DGI", action: 427, menuId: 282, xmlid: "restaurant_core.menu_restaurant_config_direct" },
        { name: "Grands Marchés & DGI", action: 437, menuId: 294, xmlid: "restaurant_core.menu_restaurant_grand_marche_admin" },
        { name: "Tableau de Bord", action: 422, menuId: 288, xmlid: "restaurant_core.menu_restaurant_dashboard" }
    ];

    function ensureAdminSidebarSections() {
        var isG = localStorage.getItem('resto_is_gerant') === 'true' || 
                  document.documentElement.classList.contains('o_resto_gerant_mode') || 
                  (document.body && document.body.classList.contains('o_resto_gerant_mode'));
        if (isG) return;

        var navbar = document.querySelector('.o_main_navbar');
        if (!navbar) return;

        // 1. Si OWL est disponible et qu'aucune app n'est sélectionnée, activer Gestion Restaurant
        if (window.odoo && window.odoo.__WOWL_DEBUG__ && window.odoo.__WOWL_DEBUG__.root) {
            var env = window.odoo.__WOWL_DEBUG__.root.env;
            if (env && env.services && env.services.menu) {
                var menuService = env.services.menu;
                if (!menuService.getCurrentApp()) {
                    var apps = menuService.getApps();
                    if (apps && apps.length) {
                        var restoApp = apps.find(function(a) {
                            return a.xmlid === 'restaurant_core.menu_restaurant_root' || (a.name && a.name.indexOf('Restaurant') !== -1);
                        }) || apps[0];
                        if (restoApp && menuService.setCurrentMenu) {
                            menuService.setCurrentMenu(restoApp);
                        }
                    }
                }
            }
        }

        // 2. Vérifier si les éléments de menu sont affichés dans .o_menu_sections
        var sectionsContainer = navbar.querySelector('.o_menu_sections');
        var visibleItems = navbar.querySelectorAll('.o_menu_sections .o_nav_entry:not(.d-none), .o_menu_sections .dropdown-item:not(.d-none), .o_restaurant_nav_entry');

        if (visibleItems.length === 0) {
            if (!sectionsContainer) {
                sectionsContainer = document.createElement('div');
                sectionsContainer.className = 'o_menu_sections';
                var systray = navbar.querySelector('.o_menu_systray');
                if (systray) {
                    navbar.insertBefore(sectionsContainer, systray);
                } else {
                    navbar.appendChild(sectionsContainer);
                }
            }

            sectionsContainer.innerHTML = '';
            ADMIN_MENU_CONFIG.forEach(function(item) {
                var link = document.createElement('a');
                link.className = 'o_nav_entry o_restaurant_nav_entry';
                link.href = '#action=' + item.action + '&menu_id=' + item.menuId;
                link.innerHTML = item.name;
                link.dataset.menuXmlid = item.xmlid;
                link.dataset.section = item.menuId;
                link.onclick = function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (window.odoo && window.odoo.__WOWL_DEBUG__ && window.odoo.__WOWL_DEBUG__.root) {
                        var env = window.odoo.__WOWL_DEBUG__.root.env;
                        if (env && env.services && env.services.action) {
                            env.services.action.doAction(item.action, { clearBreadcrumbs: true });
                            return;
                        }
                    }
                    window.location.hash = '#action=' + item.action + '&menu_id=' + item.menuId;
                };
                sectionsContainer.appendChild(link);
            });
        }
    }

    function syncBrandFromAPI() {
        fetch('/restaurant/api/brand', { cache: 'no-store' })
            .then(function(r) { return r.json(); })
            .then(function(data) {
                if (data) renderOrUpdateBrand(data);
                ensureAdminSidebarSections();
            })
            .catch(function() {
                ensureAdminSidebarSections();
            });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            renderOrUpdateBrand(null);
            ensureAdminSidebarSections();
            syncBrandFromAPI();
        });
    } else {
        renderOrUpdateBrand(null);
        ensureAdminSidebarSections();
        syncBrandFromAPI();
    }

    setInterval(syncBrandFromAPI, 2000);
    setInterval(ensureAdminSidebarSections, 1000);
    window.addEventListener('focus', function() {
        syncBrandFromAPI();
        ensureAdminSidebarSections();
    });
    window.addEventListener('hashchange', function() {
        syncBrandFromAPI();
        ensureAdminSidebarSections();
    });

    // Gestion sécurisée des clics sur les menus spécifiques
    document.addEventListener('click', function(ev) {
        var target = ev.target && ev.target.closest && ev.target.closest('.o_nav_entry, a[data-menu-xmlid]');
        if (!target) return;

        // 1. Menu ADMIN : Commandes & Ventes Encaissées -> Ouvrir l'action de supervision globale
        if ((target.dataset && target.dataset.menuXmlid === 'restaurant_core.menu_restaurant_orders') ||
            (target.innerText && target.innerText.trim() === 'Commandes & Ventes Encaissées')) {
            if (window.odoo && window.odoo.__WOWL_DEBUG__ && window.odoo.__WOWL_DEBUG__.root && window.odoo.__WOWL_DEBUG__.root.env && window.odoo.__WOWL_DEBUG__.root.env.services && window.odoo.__WOWL_DEBUG__.root.env.services.action) {
                ev.preventDefault();
                ev.stopPropagation();
                window.odoo.__WOWL_DEBUG__.root.env.services.action.doAction("restaurant_core.action_restaurant_sales_monitoring", { clearBreadcrumbs: true });
            }
            return;
        }

        // 2. Menu GÉRANT : Mes Ventes & Reçus Caisse -> Ouvrir ses propres ventes uniquement si c'est un gérant
        var isG = localStorage.getItem('resto_is_gerant') === 'true' || document.body.classList.contains('o_resto_gerant_mode');
        if (isG && ((target.dataset && target.dataset.menuXmlid === 'restaurant_core.menu_restaurant_gerant_orders') ||
            (target.innerText && (target.innerText.indexOf('Mes Ventes') !== -1 || target.innerText.indexOf('Reçus Caisse') !== -1)))) {
            if (window.odoo && window.odoo.__WOWL_DEBUG__ && window.odoo.__WOWL_DEBUG__.root && window.odoo.__WOWL_DEBUG__.root.env && window.odoo.__WOWL_DEBUG__.root.env.services && window.odoo.__WOWL_DEBUG__.root.env.services.action) {
                ev.preventDefault();
                ev.stopPropagation();
                window.odoo.__WOWL_DEBUG__.root.env.services.action.doAction("restaurant_core.action_restaurant_gerant_own_orders", { clearBreadcrumbs: true });
            }
            return;
        }
    }, true);
})();
